/// `0x005f3180`: release the pointer in slot word 0 and clear the slot.
/// Returns whether the pointer was non-null.
pub fn a48_release_pointer(slot: &mut u32) -> bool {
    let present = *slot != 0;
    *slot = 0;
    present
}

