/// to the head itself, count at +8 is cleared.  Returns the old +4 link; when
/// it differs from the head the caller must destroy the old nodes.
pub fn w25a40_list_reset_876af0(head: &mut [u32; 3], head_addr: u32) -> u32 {
    let old = head[1];
    head[1] = head_addr;
    head[0] = head_addr;
    head[2] = 0;
    old
}

