        assert_eq!(w25a44_find_state_c_slot(&t), 0x83);
        t[0x1b8 + 0x24] = 0x0c;
        assert_eq!(w25a44_find_state_c_slot(&t), 0x81);
        t[0x1b8] = 0x0c;
