        assert_eq!(calls, vec![0x1000]);
        assert_eq!(
            w26a03_reset_slot_310(0x2001, |t| calls.push(t)),
            (0x2001, true)
        );
        assert_eq!(calls, vec![0x1000, 0x2000]);
        assert_eq!(w26a03_reset_slot_310(0, |_| panic!()), (0, false));
