        t[8 + 9] = 9;
        t[8 + 10..8 + 14].copy_from_slice(&0x8000_0010u32.to_le_bytes());
        let s = w27a05_read_slot(&t, 1, 0x100).unwrap();
        assert_eq!((s.lo, s.hi, s.offset), (7, 9, 0x110));
        assert_eq!(w27a05_read_slot(&t, 5, 0).unwrap().lo, 0);
